function getSampleRateFromFormat(format) {
    if (!format || typeof format !== 'string') {
        return 48000;
    }
    if (format.includes('opus')) {
        return 48000;
    }
    let match = format.match(/(\d+)khz|(\d+)hz/);
    if (match) {
        return match[1] ? parseInt(match[1]) * 1000 : parseInt(match[2]);
    }
    return 48000;
}

function ParallelAudioManager(sentences, options) {
    this.sentences = sentences;
    this.options = options;
    this.currentIndex = 0;
    this.audioStreams = new Map();
    this.pendingStreams = new Set();
    this.isComplete = false;
    this.maxParallel = 8;

    this.startParallelLoading();
}

ParallelAudioManager.prototype = {
    startParallelLoading: function() {
        for (let i = 0; i < Math.min(this.maxParallel, this.sentences.length); i++) {
            this.loadAudioStream(i);
        }
    },

    loadAudioStream: function(index) {
        if (index >= this.sentences.length || this.audioStreams.has(index) || this.pendingStreams.has(index)) {
            return;
        }

        let self = this;
        let sentence = this.sentences[index];
        this.pendingStreams.add(index);

        let runnable = new java.lang.Runnable({
            run: function() {
                try {
                    let textSsml = specialCharReplace(sentence);

                    let styleExpression = "";
                    if (self.options.autoStyle) {
                        styleExpression = `<mstts:express-as style="auto">`;
                    } else {
                        styleExpression = `<mstts:express-as style="${self.options.style}" styledegree="${self.options.styleDegree}" role="${self.options.role}">`;
                    }

                    let ssml = `<?xml version="1.0" encoding="UTF-8"?>
<speak version="1.0" xmlns="http://www.w3.org/2001/10/synthesis" xmlns:mstts="http://www.w3.org/2001/mstts" xml:lang="${self.options.locale}">
    <voice name="${self.options.voice}">
        ${styleExpression}
            <prosody rate="${self.options.rate}%" pitch="${self.options.pitch}%" volume="${self.options.volume}%">
                ${self.options.langSkill ? `<lang xml:lang="${self.options.langSkill}">${textSsml}</lang>` : textSsml}
            </prosody>
        </mstts:express-as>
    </voice>
</speak>`;

                    let audioStream = getAudioInternal(ssml, self.options.format);
                    self.audioStreams.set(index, {
                        stream: audioStream.stream,
                        isUsed: false
                    });
                } catch (e) {
                    self.audioStreams.set(index, {
                        error: true,
                        isUsed: false
                    });
                } finally {
                    self.pendingStreams.delete(index);
                }
            }
        });

        let thread = new java.lang.Thread(runnable);
        thread.start();
    },

    preloadNextStream: function() {
        let nextIndex = this.currentIndex + this.maxParallel;
        if (nextIndex < this.sentences.length && !this.audioStreams.has(nextIndex) && !this.pendingStreams.has(nextIndex)) {
            this.loadAudioStream(nextIndex);
        }
    },

    read: function(buffer, offset, length) {
        if (this.isComplete) {
            return -1;
        }

        let currentAudio = this.audioStreams.get(this.currentIndex);

        if (!currentAudio || currentAudio.error) {
            return this.advanceToNextStream(buffer, offset, length);
        }

        if (!currentAudio.stream) {
            java.lang.Thread.sleep(2);
            return 0;
        }

        try {
            let bytesRead = currentAudio.stream.read(buffer, offset, length);

            if (bytesRead === -1) {
                return this.advanceToNextStream(buffer, offset, length);
            }

            this.preloadNextStream();
            return bytesRead;

        } catch (e) {
            return this.advanceToNextStream(buffer, offset, length);
        }
    },

    advanceToNextStream: function(buffer, offset, length) {
        if (this.currentIndex < this.sentences.length - 1) {
            this.currentIndex++;
            this.preloadNextStream();
            return this.read(buffer, offset, length);
        } else {
            this.isComplete = true;
            return -1;
        }
    },

    available: function() {
        if (this.isComplete) {
            return 0;
        }

        let currentAudio = this.audioStreams.get(this.currentIndex);
        if (currentAudio && currentAudio.stream) {
            try {
                return currentAudio.stream.available();
            } catch (e) {
                return 2048;
            }
        }

        let nextAudio = this.audioStreams.get(this.currentIndex + 1);
        if (nextAudio && nextAudio.stream) {
            return 2048;
        }

        return 0;
    },

    close: function() {
        this.isComplete = true;
        for (let [index, audio] of this.audioStreams.entries()) {
            if (audio.stream) {
                try {
                    audio.stream.close();
                } catch (e) {}
            }
        }
    }
}

