function getAudioInternalCustom(url) {
    let headers = {
        "User-Agent": "TTS-Client/1.0",
        "Accept": "audio/*"
    }

    let resp = ttsrv.httpGet(url, headers);
    if (resp.code() !== 200) {
        // 震动提示
        vibrateForError(resp.code());
        throw "音频获取失败: HTTP-" + resp.code() + ", URL: " + url;
    }

    let contentType = resp.header("Content-Type");
    if (contentType && contentType.includes("audio")) {
        return resp.body().byteStream();
    } else {
        let errorText = resp.body().string();
        // 震动提示
        vibrateForError(resp.code());
        throw "服务器返回错误: " + errorText;
    }
}

function vibrateForError(statusCode) {
    try {
        let pattern = [];
        switch(statusCode) {
            case 400:
                pattern = [0, 1000]; // 长震动1秒
                break;
            case 401:
                pattern = [0, 600, 400, 400]; // 长震动600ms + 短震动400ms
                break;
            case 403:
                pattern = [0, 200, 200, 200]; // 两次短震动，各200ms
                break;
            case 404:
                pattern = [0, 100, 100, 100, 100, 100]; // 三次震动，各100ms
                break;
            default:
                pattern = [0, 500]; // 默认震动500ms
        }

        if (ttsrv.vibrate) {
            ttsrv.vibrate(pattern, -1);
        }
    } catch (e) {
        // 忽略震动错误
    }
}

function splitIntoSentences(text) {
    if (text.length < 10) {
        return [text];
    }

    let sentences = [];
    let current = "";
    let chars = Array.from(text);

    for (let i = 0; i < chars.length; i++) {
        current += chars[i];

        let isPunctuation = /[。！？；.!?;]/.test(chars[i]);
        let isNaturalBreak = current.length >= 20 && /[，,、]/.test(chars[i]);

        if (isPunctuation || isNaturalBreak || i === chars.length - 1) {
            if (current.trim().length > 0) {
                sentences.push(current.trim());
            }
            current = "";
        }
    }

    if (sentences.length <= 1 && text.length > 20) {
        sentences = text.split(/[，,、]/).filter(s => s.trim().length > 0);
    }

    return sentences.length > 0 ? sentences : [text];
}

function specialCharReplace(s) {
    return s.replace(/[&<>"']/g, function(match) {
        switch(match) {
            case '&': return '&amp;';
            case '<': return '&lt;';
            case '>': return '&gt;';
            case '"': return '&quot;';
            case "'": return '&apos;';
            default: return match;
        }
    });
}

let ep = "";
let endpointCacheTime = 0;
const ENDPOINT_CACHE_DURATION = 30 * 60 * 1000;

function getAudioInternalOfficial(ssml, format) {
    let startTime = Date.now();
    try {
        ep ||= getEndpoint();
        let sharedPref = appContext.getSharedPreferences("microsoft_tts", android.content.Context.MODE_PRIVATE);
        let selectedRegion = sharedPref.getString("selectedRegion", "eastasia");
        let url = "https://" + selectedRegion + ".tts.speech.microsoft.com/cognitiveservices/v1";
        let headers = {
            Authorization: ep['t'],
            "Content-Type": "application/ssml+xml",
            "X-Microsoft-OutputFormat": format,
            "User-Agent": "TTS-Plugin/2.0"
        };

        let resp = ttsrv.httpPost(url, ssml, headers);
        if (resp.code() !== 200) {
            let errorBody = resp.body().string();
            ep = '';
            endpointCacheTime = 0;
            throw "音频获取失败: " + resp.code();
        }

        let fetchTime = Date.now() - startTime;
        return {
            stream: resp.body().byteStream(),
            fetchTime: fetchTime
        };
    } catch (e) {
        ep = '';
        endpointCacheTime = 0;
        throw e;
    }
}

let endpointUrl = "https://dev.microsofttranslator.com/apps/endpoint?api-version=1.0";

function getEndpoint() {
    let currentTime = java.lang.System.currentTimeMillis();
    if (ep && (currentTime - endpointCacheTime) < ENDPOINT_CACHE_DURATION) {
        return ep;
    }

    let sign = getSign();

    let headers = {
        "Accept-Language": "zh-Hans",
        "X-ClientVersion": "4.0.530a 5fe1dc6c",
        "X-UserId": "0f04d16a175c411e",
        "X-HomeGeographicRegion": "zh-Hans-CN",
        "X-ClientTraceId": "aab069b9-70a7-4844-a734-96cd78d94be9",
        "X-MT-Signature": sign,
        "User-Agent": "okhttp/4.5.0",
        "Content-Type": "application/json; charset=utf-8",
        "Content-Length": "0",
        "Accept-Encoding": "gzip"
    };

    let resp = ttsrv.httpPost(endpointUrl, "", headers);
    if (resp.code() !== 200) {
        throw "终结点信息获取失败: " + resp.code();
    }
    let str = resp.body().string();
    ep = JSON.parse(str);
    endpointCacheTime = currentTime;
    return ep;
}

function getSign() {
    let aly = new JavaImporter(
        javax.crypto.Mac,
        javax.crypto.spec.SecretKeySpec,
        java.net.URLEncoder,
        java.lang.String,
        java.text.SimpleDateFormat,
        java.util.Locale,
        java.util.TimeZone,
        android.util.Base64
    );
    with(aly) {
        function percentEncode(value) {
            return URLEncoder.encode(value, 'UTF-8');
        }

        function dateFormat() {
            let simpleDateFormat = new SimpleDateFormat("EEE, dd MMM yyyy HH:mm:ss", Locale.US);
            simpleDateFormat.setTimeZone(TimeZone.getTimeZone("GMT"));
            return simpleDateFormat.format(new Date()).toLowerCase() + "GMT";
        }

        function sign(url) {
            url = url.split('://')[1];

            let encodeUrl = percentEncode(url);
            let uuid = ttsrv.randomUUID().replaceAll("-", "");
            let formattedDate = dateFormat();
            let bytes = String.format("%s%s%s%s", "MSTranslatorAndroidApp", encodeUrl, formattedDate, uuid).toLowerCase().getBytes('UTF-8');

            let secretKeySpec = new SecretKeySpec(Base64.decode("oik6PdDdMnOXemTbwvMn9de/h9lFnfBaCWbGMMZqqoSaQaqUOqjVGm5NqsmjcBI1x+sS9ugjB55HEJWRiFXYFw==", 2), "HmacSHA256");
            var mac = Mac.getInstance('HmacSHA256');
            mac.init(secretKeySpec);
            var signData = mac.doFinal(bytes);
            var signBase64 = Base64.encodeToString(signData, Base64.NO_WRAP);
            return String.format("%s::%s::%s::%s", "MSTranslatorAndroidApp", signBase64, formattedDate, uuid);
        }
    }
    return sign(endpointUrl);
}

