    onVoiceChanged: function(locale, voiceCode) {
        try {
            java.lang.Thread.sleep(50);
        } catch (e) {}

        let sharedPref = appContext.getSharedPreferences("microsoft_tts", android.content.Context.MODE_PRIVATE);
        let vic = currentVoices.get(voiceCode);
        if (!vic) return;

        let locale2List = vic['SecondaryLocaleList'];
        let locale2Items = [];
        let locale2Pos = 0;
        if (locale2List) {
            locale2Items.push(Item("默认", ""));
            locale2List.map(function(v, i) {
                try {
                    let loc = java.util.Locale.forLanguageTag(v);
                    let name = loc.getDisplayName(loc);
                    locale2Items.push(Item(name, v));
                    if (v === sharedPref.getString("languageSkill", "")) {
                        locale2Pos = i + 1;
                    }
                } catch (e) {}
            });
        }
        skillSpinner.items = locale2Items;
        skillSpinner.selectedPosition = locale2Pos;
        skillSpinner.visibility = locale2Items.length > 0 ? View.VISIBLE : View.GONE;

        let styles = vic['StyleList'];
        let styleItems = [];
        let stylePos = 0;
        if (styles) {
            styleItems.push(Item("默认", "default"));
            styles.map(function(v, i) {
                styleItems.push(Item(getString(v), v));
                if (v === sharedPref.getString("style", "default")) {
                    stylePos = i + 1;
                }
            });
        }
        styleSpinner.items = styleItems;
        styleSpinner.selectedPosition = stylePos;

        let roles = vic['RolePlayList'];
        let roleItems = [];
        let rolePos = 0;
        if (roles) {
            roleItems.push(Item("默认", "default"));
            roles.map(function(v, i) {
                roleItems.push(Item(getString(v), v));
                if (v === sharedPref.getString("role", "default")) {
                    rolePos = i + 1;
                }
            });
        }
        roleSpinner.items = roleItems;
        roleSpinner.selectedPosition = rolePos;

        let autoStyleEnabled = sharedPref.getBoolean("autoStyle", false);
        updateStyleControlsVisibility(autoStyleEnabled);

        if (!autoStyleEnabled && styleDegreeEditText && styleDegreeLabel) {
            let styleSelected = styleSpinner.selectedPosition > 0 && styleSpinner.items[styleSpinner.selectedPosition].value;
            let visible = styleSelected && styles;
            styleDegreeEditText.setVisibility(visible ? View.VISIBLE : View.GONE);
            styleDegreeLabel.setVisibility(visible ? View.VISIBLE : View.GONE);
        }
    }
}

function updateStyleControlsVisibility(autoStyleEnabled) {
    if (styleSpinner) {
        styleSpinner.setVisibility(autoStyleEnabled ? View.GONE : View.VISIBLE);
    }
    if (roleSpinner) {
        roleSpinner.setVisibility(autoStyleEnabled ? View.GONE : View.VISIBLE);
    }
    if (styleDegreeEditText) {
        styleDegreeEditText.setVisibility(autoStyleEnabled ? View.GONE : View.VISIBLE);
    }
    if (styleDegreeLabel) {
        styleDegreeLabel.setVisibility(autoStyleEnabled ? View.GONE : View.VISIBLE);
    }
}

function updateServerControlsVisibility(useCustomServer) {
    if (serverSpinner) {
        serverSpinner.setVisibility(useCustomServer ? View.VISIBLE : View.GONE);
    }
    if (manualServerSwitch) {
        manualServerSwitch.setVisibility(useCustomServer ? View.VISIBLE : View.GONE);
    }
    if (serverUrlEditText) {
        let sharedPref = appContext.getSharedPreferences("microsoft_tts", android.content.Context.MODE_PRIVATE);
        let useManualServer = sharedPref.getBoolean("manualServerInput", false);
        serverUrlEditText.setVisibility(useCustomServer && useManualServer ? View.VISIBLE : View.GONE);
    }
}

